// Spring Boot - Add X-Frame-Options via Security Configuration
// SecurityConfig.java

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.web.SecurityFilterChain;

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
            .headers(headers -> headers
                // Option 1: DENY - Block all framing (recommended for most apps)
                .frameOptions(frameOptions -> frameOptions.deny())

                // Option 2: SAMEORIGIN - Allow same-origin framing only
                // .frameOptions(frameOptions -> frameOptions.sameOrigin())

                // Also add CSP frame-ancestors for modern browsers
                .contentSecurityPolicy(csp -> csp
                    .policyDirectives("frame-ancestors 'none'")
                    // Use "frame-ancestors 'self'" if using SAMEORIGIN
                )
            )
            .authorizeHttpRequests(auth -> auth
                .anyRequest().permitAll()
            );

        return http.build();
    }
}

// Alternative: Manual Filter approach
import javax.servlet.*;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import org.springframework.stereotype.Component;

@Component
public class XFrameOptionsFilter implements Filter {

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, 
                        FilterChain chain) throws IOException, ServletException {
        HttpServletResponse httpResponse = (HttpServletResponse) response;

        // Set X-Frame-Options header
        httpResponse.setHeader("X-Frame-Options", "DENY");
        // Or: httpResponse.setHeader("X-Frame-Options", "SAMEORIGIN");

        // Also set CSP frame-ancestors for defense-in-depth
        httpResponse.setHeader("Content-Security-Policy", "frame-ancestors 'none'");

        chain.doFilter(request, response);
    }
}

