const express = require('express');
const helmet = require('helmet');

const app = express();

// Method 1: Use helmet (recommended)
app.use(helmet.frameguard({ action: 'deny' }));
// Or for SAMEORIGIN:
// app.use(helmet.frameguard({ action: 'sameorigin' }));

// Also add CSP frame-ancestors for modern browsers
app.use(
  helmet.contentSecurityPolicy({
    directives: {
      frameAncestors: ["'none'"],
      // Or: frameAncestors: ["'self'"] for SAMEORIGIN equivalent
    },
  })
);

// Method 2: Manual middleware (if not using helmet)
app.use((req, res, next) => {
  res.setHeader('X-Frame-Options', 'DENY');
  // Or: res.setHeader('X-Frame-Options', 'SAMEORIGIN');

  // Also set CSP frame-ancestors
  res.setHeader('Content-Security-Policy', "frame-ancestors 'none'");

  next();
});

// Method 3: Use helmet with all security headers
app.use(
  helmet({
    frameguard: {
      action: 'deny',
    },
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        frameAncestors: ["'none'"],
      },
    },
  })
);

app.get('/', (req, res) => {
  res.send('<h1>Protected from clickjacking</h1>');
});

app.listen(3000, () => {
  console.log('Server running with X-Frame-Options protection');
});

