const request = require('supertest');
const { expect } = require('chai');
const app = require('../app');

describe('X-Frame-Options Header Tests', () => {
  it('should have X-Frame-Options header', (done) => {
    request(app)
      .get('/')
      .expect(200)
      .expect('X-Frame-Options', 'DENY')
      .end(done);
  });

  it('should have CSP frame-ancestors directive', (done) => {
    request(app)
      .get('/')
      .end((err, res) => {
        if (err) return done(err);

        const csp = res.headers['content-security-policy'];
        expect(csp).to.exist;
        expect(csp).to.include("frame-ancestors 'none'");

        done();
      });
  });

  it('should protect all routes', (done) => {
    const routes = ['/', '/api/data', '/login', '/dashboard'];
    let completed = 0;

    routes.forEach(route => {
      request(app)
        .get(route)
        .end((err, res) => {
          if (!err) {
            expect(res.headers['x-frame-options']).to.equal('DENY');
          }
          completed++;
          if (completed === routes.length) done();
        });
    });
  });

  it('should not allow ALLOW-FROM (deprecated)', (done) => {
    request(app)
      .get('/')
      .end((err, res) => {
        if (err) return done(err);

        const xfo = res.headers['x-frame-options'];
        expect(xfo).to.not.include('ALLOW-FROM');

        done();
      });
  });
});

