using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddControllersWithViews();

var app = builder.Build();

// Method 1: Use Antiforgery middleware (includes X-Frame-Options)
app.UseAntiforgery();

// Method 2: Manual middleware for X-Frame-Options
app.Use(async (context, next) =>
{
    // Set X-Frame-Options header
    context.Response.Headers.Add("X-Frame-Options", "DENY");
    // Or: context.Response.Headers.Add("X-Frame-Options", "SAMEORIGIN");

    // Also set CSP frame-ancestors for defense-in-depth
    context.Response.Headers.Add(
        "Content-Security-Policy", 
        "frame-ancestors 'none'"
    );

    await next();
});

app.UseRouting();
app.UseAuthorization();

app.MapControllerRoute(
    name: "default",
    pattern: "{controller=Home}/{action=Index}/{id?}");

app.Run();

// Alternative: Create reusable middleware class
public class XFrameOptionsMiddleware
{
    private readonly RequestDelegate _next;
    private readonly string _policy;

    public XFrameOptionsMiddleware(RequestDelegate next, string policy = "DENY")
    {
        _next = next;
        _policy = policy; // "DENY" or "SAMEORIGIN"
    }

    public async Task InvokeAsync(HttpContext context)
    {
        context.Response.Headers.Add("X-Frame-Options", _policy);

        // Add CSP frame-ancestors
        var frameAncestors = _policy == "DENY" ? "'none'" : "'self'";
        context.Response.Headers.Add(
            "Content-Security-Policy", 
            $"frame-ancestors {frameAncestors}"
        );

        await _next(context);
    }
}

// Extension method for easy registration
public static class XFrameOptionsExtensions
{
    public static IApplicationBuilder UseXFrameOptions(
        this IApplicationBuilder builder, 
        string policy = "DENY")
    {
        return builder.UseMiddleware<XFrameOptionsMiddleware>(policy);
    }
}

// Usage in Program.cs:
// app.UseXFrameOptions("DENY");

