# Method 1: Use Django's built-in XFrameOptionsMiddleware
MIDDLEWARE = [
    'django.middleware.security.SecurityMiddleware',
    'django.middleware.clickjacking.XFrameOptionsMiddleware',  # Add this
    # ... other middleware
]

# Configure X-Frame-Options policy
X_FRAME_OPTIONS = 'DENY'  # Block all framing
# Or:
# X_FRAME_OPTIONS = 'SAMEORIGIN'  # Allow same-origin framing

# Method 2: Use SecurityMiddleware with CSP
SECURE_CONTENT_SECURITY_POLICY = {
    'frame-ancestors': ["'none'"],  # Modern alternative to X-Frame-Options
}

# Method 3: Custom middleware for more control
# middleware.py
class CustomXFrameOptionsMiddleware:
    def __init__(self, get_response):
        self.get_response = get_response

    def __call__(self, request):
        response = self.get_response(request)

        # Set X-Frame-Options header
        response['X-Frame-Options'] = 'DENY'

        # Also set CSP frame-ancestors for defense-in-depth
        if 'Content-Security-Policy' in response:
            response['Content-Security-Policy'] += "; frame-ancestors 'none'"
        else:
            response['Content-Security-Policy'] = "frame-ancestors 'none'"

        return response

# Method 4: Decorator for specific views
from django.views.decorators.clickjacking import xframe_options_deny
from django.views.decorators.clickjacking import xframe_options_sameorigin

@xframe_options_deny
def sensitive_view(request):
    return HttpResponse('This view cannot be framed')

@xframe_options_sameorigin
def iframe_compatible_view(request):
    return HttpResponse('This view can be framed by same origin')

# Method 5: Exempt specific views from X-Frame-Options
from django.views.decorators.clickjacking import xframe_options_exempt

@xframe_options_exempt
def embeddable_widget_view(request):
    # This view can be embedded anywhere
    return HttpResponse('Embeddable widget')

