# Nginx - Add X-Frame-Options header
# /etc/nginx/sites-available/your-site or /etc/nginx/nginx.conf

server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name your-domain.com;

    # Add X-Frame-Options header
    add_header X-Frame-Options "DENY" always;
    # Or for same-origin framing:
    # add_header X-Frame-Options "SAMEORIGIN" always;

    # Also add CSP frame-ancestors for defense-in-depth
    add_header Content-Security-Policy "frame-ancestors 'none'" always;
    # Or for same-origin:
    # add_header Content-Security-Policy "frame-ancestors 'self'" always;

    # Other recommended security headers
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-XSS-Protection "1; mode=block" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;

    location / {
        # Your application config
        proxy_pass http://backend;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}

# Note: 'always' ensures header is added even for error responses

