// Selenium test for X-Frame-Options validation
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.chrome.ChromeOptions;
import org.openqa.selenium.logging.LogEntries;
import org.openqa.selenium.logging.LogEntry;
import org.openqa.selenium.logging.LogType;
import org.testng.annotations.Test;
import org.testng.Assert;

public class XFrameOptionsTest {

    @Test
    public void verifyXFrameOptionsHeaderPresent() {
        ChromeOptions options = new ChromeOptions();
        options.setCapability("goog:loggingPrefs", 
            Map.of("browser", "ALL", "performance", "ALL"));

        WebDriver driver = new ChromeDriver(options);

        try {
            driver.get("https://your-domain.com");

            // Get performance logs to check response headers
            LogEntries logs = driver.manage().logs().get(LogType.PERFORMANCE);

            boolean xfoHeaderFound = false;
            for (LogEntry entry : logs) {
                String message = entry.getMessage();
                if (message.contains("X-Frame-Options") && 
                    (message.contains("DENY") || message.contains("SAMEORIGIN"))) {
                    xfoHeaderFound = true;
                    System.out.println("Found X-Frame-Options: " + message);
                    break;
                }
            }

            Assert.assertTrue(xfoHeaderFound, 
                "X-Frame-Options header should be present with value DENY or SAMEORIGIN");

        } finally {
            driver.quit();
        }
    }

    @Test
    public void verifyIframeEmbeddingBlocked() {
        WebDriver driver = new ChromeDriver();

        try {
            // Create test HTML with iframe
            String iframeHtml = 
                "<html><body>" +
                "<iframe id='testFrame' src='https://your-domain.com' " +
                "width='800' height='600'></iframe>" +
                "</body></html>";

            // Load test page
            driver.get("data:text/html," + iframeHtml);

            // Get browser console logs
            LogEntries logs = driver.manage().logs().get(LogType.BROWSER);

            boolean frameBlockedErrorFound = false;
            for (LogEntry entry : logs) {
                String message = entry.getMessage();
                if (message.contains("X-Frame-Options") || 
                    message.contains("Refused to display")) {
                    frameBlockedErrorFound = true;
                    System.out.println("Frame blocking error: " + message);
                    break;
                }
            }

            Assert.assertTrue(frameBlockedErrorFound, 
                "Browser should log X-Frame-Options violation when iframe is blocked");

        } finally {
            driver.quit();
        }
    }

    @Test
    public void verifyAllCriticalPagesProtected() {
        WebDriver driver = new ChromeDriver();

        String[] criticalPages = {
            "https://your-domain.com/",
            "https://your-domain.com/login",
            "https://your-domain.com/dashboard",
            "https://your-domain.com/checkout"
        };

        try {
            for (String page : criticalPages) {
                driver.get(page);

                // Check logs for X-Frame-Options header
                LogEntries logs = driver.manage().logs().get(LogType.PERFORMANCE);
                boolean headerFound = false;

                for (LogEntry entry : logs) {
                    if (entry.getMessage().contains("X-Frame-Options")) {
                        headerFound = true;
                        break;
                    }
                }

                Assert.assertTrue(headerFound, 
                    "Page " + page + " should have X-Frame-Options header");
            }

        } finally {
            driver.quit();
        }
    }
}
